const msg = $json.message || {};
const LF = String.fromCharCode(10);
const userId = String((msg.from && msg.from.id) || '');
const chatId = String((msg.chat && msg.chat.id) || '');
const isPrivate = !!msg.chat && msg.chat.type === 'private';
const isBot = !!(msg.from && msg.from.is_bot);
const username = String((msg.from && msg.from.username) || '').toLowerCase();
const allowed = String($json.allowed_user_ids || '').toLowerCase().split(/[,;\s]+/).map((s) => s.replace(/^@/, '')).filter(Boolean);
const text = String(msg.text || '').trim();
const allowedSender = isPrivate && !isBot && userId !== '' && (allowed.includes(userId) || (username !== '' && allowed.includes(username)));

let mode = 'ignore';
let request = {};
let reply_text = '';
const help = [
  'Arthur Voss (ThesisLab, paper trading only).',
  'Send an investment thesis in plain English, e.g. "MSFT beats SPY over 20 days $500".',
  'Commands: APPROVE <id>, REJECT <id>, EVALUATE <id>, CLOSE <id> [EARLY].',
].join(LF);

if (/^\/(myid|id)\b/i.test(text) && isPrivate) {
  mode = 'reply_only';
  reply_text = 'Your Telegram user ID is ' + userId + (username ? ' (username @' + username + ')' : '') + '.' + (allowedSender ? ' You are authorized.' : ' You are not authorized yet; ask the owner to add this ID.');
} else if (allowedSender) {
  const cmd = text.match(/^\s*\/?(APPROVE|REJECT|EVALUATE|CLOSE)\s+(TL-[A-Z0-9-]+)(\s+EARLY)?/i);
  if (/^\/(start|help)\b/i.test(text)) {
    mode = 'reply_only';
    reply_text = help;
  } else if (cmd) {
    const verb = cmd[1].toUpperCase();
    const id = cmd[2].toUpperCase();
    if (verb === 'APPROVE') request = { action: 'approve_trade', experiment_id: id, confirm: true };
    if (verb === 'REJECT') request = { action: 'reject', experiment_id: id };
    if (verb === 'EVALUATE') request = { action: 'evaluate', experiment_id: id };
    if (verb === 'CLOSE') request = { action: 'close_position', experiment_id: id, confirm: true, early_exit: !!cmd[3] };
    mode = 'api';
  } else if (text.length >= 10) {
    const amt = text.match(/\$\s?([0-9][0-9,]*)/);
    request = { action: 'analyze', thesis: text.slice(0, 4000), notional_usd: amt ? Number(amt[1].replace(/,/g, '')) : 0 };
    mode = 'api';
  } else {
    mode = 'reply_only';
    reply_text = help;
  }
}

return { json: { mode, user_id: userId, chat_id: chatId, request, reply_text, api_url: $json.api_url } };

const r = $json || {};
const src = $('Parse Telegram Command').item.json;
const req = src.request || {};
const LF = String.fromCharCode(10);
const L = [];
const p = r.proposal || {};
if (!r || Object.keys(r).length === 0 || (r.ok === undefined && !r.action)) {
  L.push('ThesisLab could not process this right now. Nothing was traded.');
} else if (r.action === 'analyze') {
  if ((r.status === 'proposed' || r.status === 'proposal') && r.experiment_id) {
    L.push('Arthur Voss: experiment ' + r.experiment_id, '');
    L.push((p.asset || '?') + ' vs ' + (p.benchmark || '?') + ', ' + (p.horizon_days || '?') + ' trading days, $' + r.notional_usd + ' paper' + (r.allocation_capped ? ' (capped by policy)' : ''));
    const risks = Array.isArray(p.risk_warnings) ? p.risk_warnings : [];
    if (p.plain_idea) L.push('', 'The Idea: ' + p.plain_idea);
    L.push('', 'The Bet: ' + (p.falsifiable_claim || '') + ' (measured by close-to-close total return)');
    if (p.reason || p.rationale) L.push('', 'The Reason: ' + (p.reason || p.rationale));
    if (p.main_risk || risks.length) L.push('', 'The Risk: ' + (p.main_risk || risks.join('; ')));
    if (p.invalidation_rule) L.push('', 'What Would Prove Us Wrong: ' + p.invalidation_rule);
    if (p.entry_rule) L.push('', 'Get in: ' + p.entry_rule);
    if (p.exit_rule) L.push('Get out: ' + p.exit_rule);
    L.push('', 'Nothing traded. Send APPROVE ' + r.experiment_id + ' to place the PAPER order, or REJECT ' + r.experiment_id + '.');
  } else {
    L.push('Arthur Voss: I could not turn this into a tradable experiment.');
    if (p.clarification_question) L.push(p.clarification_question);
    if (Array.isArray(r.validation_errors) && r.validation_errors.length) L.push('Issues: ' + r.validation_errors.join('; '));
    L.push('No order possible. Send a revised thesis.');
  }
} else if (r.action === 'approve_trade') {
  if (r.ok) L.push('PAPER order placed for ' + r.experiment_id + ': ' + r.symbol + ' $' + r.notional_usd + ', order ' + r.paper_order_id + ' (' + r.order_status + '). Fills next session if the market is closed.', 'Later: EVALUATE ' + r.experiment_id + ' or CLOSE ' + r.experiment_id + '.');
  else L.push('Approval of ' + (r.experiment_id || req.experiment_id) + ' blocked. No order placed. ' + ((r.reasons || []).join('; ') || r.error || ''));
} else if (r.action === 'reject') {
  L.push(r.ok ? r.experiment_id + ' rejected. No order placed.' : 'Could not reject ' + (r.experiment_id || req.experiment_id) + ': not found or no longer pending.');
} else if (r.action === 'evaluate') {
  if (r.ok && r.outcome) {
    const o = r.outcome;
const VL = (v) => { const s = String(v || ''); const base = s.replace(/^interim_/, ''); const m = { supported: 'Held up', rejected: "Didn't hold up", inconclusive: 'Too close to call' }; return (s.indexOf('interim_') === 0 ? 'Early read: ' : '') + (m[base] || s); };
    L.push('Results ' + r.experiment_id + ':');
    L.push('The Verdict: ' + (o.verdict_label || VL(o.verdict)));
    L.push('Our pick ' + o.asset_return + ' vs benchmark ' + o.benchmark_return + ' (difference ' + o.alpha + ')');
    L.push(o.trading_days_elapsed + ' of ' + o.horizon_days + ' trading days' + (o.horizon_complete ? ', test complete' : ''));
    L.push('', 'Position still open. Send CLOSE ' + r.experiment_id + ' after the horizon (add EARLY to exit now).');
  } else L.push('Could not evaluate ' + (r.experiment_id || req.experiment_id) + ': ' + (r.error || 'unknown error'));
} else if (r.action === 'close_position') {
  if (r.ok) L.push('PAPER position closed for ' + r.experiment_id + ': sold ' + r.qty + ' ' + r.symbol + ', order ' + r.sell_order_id + ' (' + r.sell_order_status + ').');
  else L.push('Close of ' + (r.experiment_id || req.experiment_id) + ' blocked. Nothing sold. ' + ((r.reasons || []).join('; ') || r.error || ''));
} else {
  L.push('Unexpected ThesisLab response. Nothing was traded.');
}
let text = L.join(LF);
if (text.length > 3800) text = text.slice(0, 3750) + LF + '(truncated)';
return { json: { chat_id: src.chat_id, reply_text: text } };
